    def removeDuplicates(self, nums: List[int]) -> int:
        pass

problems.solutionCode:
class Solution:
    def removeDuplicates(self, nums: List[int]) -> int:
        k = 0
        for x in nums:
            if k == 0 or x != nums[k - 1]:
                nums[k] = x
                k += 1
        return k

